      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória na Heap gerenciada a cada frame dentro do método Update(), causada por concatenação reiterada de strings em loop ('s += i.ToString()') e instanciação repetida de arrays ('new object[10000]'). No frame analisado, foram alocados mais de 5.4 MB de lixo em um único frame, forçando o Garbage Collector a travar a thread principal por 25.84ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private StringBuilder _cachedStringBuilder;
        private object[][] _reusableBlocks;

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
            _cachedStringBuilder = new StringBuilder(4096);
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                var col = quad.GetComponent<Collider>();
                if (col != null) Destroy(col);
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                // Usar StringBuilder e buffers prealocados para evitar GC.Alloc
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }

                if (gcArrayAllocs > 0)
                {
                    if (_reusableBlocks == null || _reusableBlocks.Length != gcArrayAllocs)
                    {
                        _reusableBlocks = new object[gcArrayAllocs][];
                        for (int i = 0; i < gcArrayAllocs; i++)
                        {
                            _reusableBlocks[i] = new object[10000];
                        }
                    }
                }
            }

            if (stressCpu)
            {
                // Em cenarios reais, evite FindObjectsOfType no Update. 
                // Armazene referencias em cache durante Start/Awake ou registre entidades em um Manager central.
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    // Usar MaterialPropertyBlock evita instanciar clones de materiais na memoria e mantem o batching
                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, strings são imutáveis. Toda vez que fazemos 's += i', uma nova string é criada na memória e a antiga vira 'lixo'. Fazer isso centenas de vezes todo frame, junto com 'new object[]', sobrecarrega a memória gerenciada. Quando a memória enche, o Unity congela o jogo para fazer a faxina (Garbage Collection), causando os engasgos (stutters). Para resolver, reutilizamos instâncias pré-alocadas (como StringBuilder e arrays reutilizáveis). Além disso, acessar 'renderer.material' cria uma cópia inteira do material na memória; substituímos isso por MaterialPropertyBlock, que altera a cor sem duplicar o material nem gerar lixo de memória."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Uso repetitivo de 'GameObject.FindObjectsOfType<GameObject>()' em loop dentro do Update(). Esse método varre linearmente toda a hierarquia da cena e aloca um array novo a cada chamada, gerando picos críticos de tempo de processador (até 102ms).",
      "codigo_refatorado": "// Para otimizar varreduras por CPU no Update, substitua a busca global por um padrao de registro:
// Em vez de FindObjectsOfType no Update:
// public static readonly HashSet<GameObject> ActiveObjects = new HashSet<GameObject>();
// Cada objeto se registra no OnEnable: ActiveObjects.Add(gameObject);
// E remove no OnDisable: ActiveObjects.Remove(gameObject);",
      "explicacao_didatica": "A função FindObjectsOfType é como procurar um documento revirando todas as gavetas do escritório do zero a cada fração de segundo. Isso consome muito processamento. O correto é guardar referências dos objetos no momento em que eles são criados ou usar listas centrais de registro, garantindo que o jogo não perca tempo procurando objetos que já existem."
    }
  ],
  "dicas_level_design": null
}

